"""Install the tested Wan HTTPS pull worker, pair locally, and run in foreground."""
import argparse
import base64
import gzip
import json
import os
import subprocess
import sys
from pathlib import Path

PAYLOAD = ""  # noqa: E501 - frozen ROG worker support


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--apply', action='store_true')
    parser.add_argument('--server', default='https://dhanzai.com')
    args = parser.parse_args()
    if not args.apply:
        print('Plan: account-scoped ROG Wan worker; outbound HTTPS only, no incoming port.')
        print('Use --apply after installing ROG worker support on AWS. No video was submitted.')
        return
    if os.geteuid() == 0 or os.environ.get('HSA_ENABLE_DXG_DETECTION') != '1':
        raise ValueError('Run as your WSL user after sourcing amd-env.sh.')
    os.umask(0o077)
    state = Path.home() / '.local/share/dhanz-rog'
    python = state / 'venv-rocm72/bin/python'
    if not python.is_file() or not (state / 'wan-model-revision.json').is_file():
        raise ValueError('Complete the successful AMD Wan preview setup first.')
    root = state / 'worker'
    root.mkdir(mode=0o700, exist_ok=True)
    root.chmod(0o700)
    sources = json.loads(gzip.decompress(base64.b64decode(PAYLOAD)))
    for name, source in sources.items():
        if name not in ('worker.py', 'preview.py'):
            raise ValueError('Unknown installer module.')
        compile(source, name, 'exec')
        target = root / name
        if target.exists() and target.read_text() != source:
            raise ValueError('An existing worker was customized; it was preserved.')
    for name, source in sources.items():
        target = root / name
        target.write_text(source)
        target.chmod(0o600)
    worker = root / 'worker.py'
    print('Worker installed privately. It uses your cached model; no model download or paid video API.', flush=True)
    if not (root / 'connection.json').is_file():
        subprocess.run([str(python), str(worker), '--pair', '--server', args.server], check=True)
    print('Starting the paired ROG worker. No old failed video is automatically retried.', flush=True)
    os.execv(str(python), [str(python), str(worker)])


if __name__ == '__main__':
    try:
        main()
    except KeyboardInterrupt:
        raise SystemExit('ROG setup stopped; existing model files were preserved.') from None
    except subprocess.CalledProcessError:
        raise SystemExit('ROG pairing or readiness check failed. Share its final message; no video was submitted.') from None
    except ValueError as exc:
        raise SystemExit(str(exc)) from None
